import json

with open('/home/ubuntu/runs/paper/qwen-hpl-u1-turns/play/users/u000/system/state/workspace/programs/task-fd68d2cd.json') as f:
    demo = json.load(f)

test_input = demo['input']

def transform(grid):
    rows, cols = len(grid), len(grid[0])
    output = [[0] * (cols // 3) for _ in range(rows // 3)]

    for out_r in range(rows // 3):
        for out_c in range(cols // 3):
            in_r, in_c = out_r * 3, out_c * 3

            block = [[grid[in_r + r][in_c + c] for c in range(3)] for r in range(3)]

            colors = {}
            for r in range(3):
                for c in range(3):
                    v = block[r][c]
                    if v != 0:
                        colors[v] = colors.get(v, 0) + 1

            if not colors:
                output[out_r][out_c] = 0
            elif len(colors) == 1:
                single = list(colors.keys())[0]
                output[out_r][out_c] = 0 if single == 5 else single
            else:
                if 5 in colors:
                    non_5_colors = [v for v in colors.keys() if v != 5]
                    edge_cells = [(r, c) for r in range(3) for c in range(3) 
                                   if r in (0, 2) or c in (0, 2)]

                    for color in non_5_colors:
                        positions = [(r, c) for r in range(3) for c in range(3) 
                                     if block[r][c] == color]
                        if any(pos in edge_cells for pos in positions):
                            output[out_r][out_c] = color
                            break
                    else:
                        output[out_r][out_c] = 0
                else:
                    values = list(colors.keys())
                    count1, count2 = colors[values[0]], colors[values[1]]
                    majority, minority = (values[0] if count1 > count2 else values[1], 
                                          values[0] if count1 < count2 else values[1])
                    output[out_r][out_c] = minority

    return output

